import { ActionMetrics, SimResult, SimResultFilter } from '../../proto_utils/sim_result.js';
import { bucket } from '../../utils.js';
import { formatDeltaTextElem } from '../../utils.js'; 

import { ColumnSortType, MetricsTable } from './metrics_table.js';
import { ResultComponent, ResultComponentConfig, SimResultData } from './result_component.js';

export class SpellMetricsTable extends MetricsTable<ActionMetrics> {
	constructor(config: ResultComponentConfig) {
		config.rootCssClass = 'spell-metrics-root';
		
		// Capture the latest result data
		let lastSimResult: SimResultData | null = null;
		config.resultsEmitter.on((eventID, resultData) => {
			lastSimResult = resultData;
		});

		// Helper to render the diffs
		const renderDiffCell = (metric: ActionMetrics, cellElem: HTMLElement, getValue: (m: ActionMetrics) => number, precision: number, isPercent: boolean = false, lowerIsBetter: boolean = false) => {
			const val = getValue(metric);
			cellElem.textContent = val.toFixed(precision) + (isPercent ? '%' : '');

			if (lastSimResult && lastSimResult.referenceResult) {
				const refPlayers = lastSimResult.referenceResult.getPlayers(lastSimResult.filter);
				if (refPlayers.length === 1) {
					const refPlayer = refPlayers[0];
					// Flatten out player and pet SPELL actions
					const allRefActions = refPlayer.getSpellActions().map(a => a.forTarget(lastSimResult!.filter))
						.concat(refPlayer.pets.flatMap(pet => pet.getSpellActions().map(a => a.forTarget(lastSimResult!.filter))));

					const refAction = allRefActions.find(a => a.actionId.equals(metric.actionId));
					if (refAction) {
						const refVal = getValue(refAction);
						if (val !== refVal) {
							const deltaSpan = document.createElement('span');
							formatDeltaTextElem(deltaSpan, refVal, val, precision, lowerIsBetter, false, false);
							
							if (isPercent) {
								deltaSpan.textContent += '%';
							}
							
							// Wrap in brackets instead of parentheses
							deltaSpan.textContent = `(${deltaSpan.textContent})`;
							
							// Styling for spacing and a smaller font
							deltaSpan.style.marginLeft = '6px';
							deltaSpan.style.fontSize = '0.60em'; // Dropped down from 0.85em
							deltaSpan.style.whiteSpace = 'nowrap'; // Prevents awkward line breaks
							
							cellElem.appendChild(deltaSpan);
						}
					}
				}
			}
		};
		
		super(config, [
			MetricsTable.nameCellConfig((metric: ActionMetrics) => {
				return {
					name: metric.name,
					actionId: metric.actionId,
				};
			}),
			{
				name: 'Damage',
				tooltip: 'Damage',
				getValue: (metric: ActionMetrics) => metric.damage,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.damage, 1),
			},
			{
				name: 'DPS',
				tooltip: 'Damage / Encounter Duration',
				sort: ColumnSortType.Descending,
				getValue: (metric: ActionMetrics) => metric.dps,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.dps, 1),
			},
			{
				name: 'Avg Cast',
				tooltip: 'Damage / Casts',
				getValue: (metric: ActionMetrics) => metric.avgCast,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.avgCast, 1),
			},
			{
				name: 'Avg Hit',
				tooltip: 'Damage / Hits',
				getValue: (metric: ActionMetrics) => metric.avgHit,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.avgHit, 1),
			},
			{
				name: 'DPET',
				tooltip: 'Damage / Avg Cast Time',
				getValue: (metric: ActionMetrics) => metric.dpet,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.dpet, 1),
			},
			{
				name: 'DPR',
				tooltip: 'Damage Per Resource Spent',
				getValue: (metric: ActionMetrics) => metric.dpr,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.dpr, 1),
			},
			{
				name: 'TPS',
				tooltip: 'Threat / Encounter Duration',
				columnClass: 'threat-metrics',
				getValue: (metric: ActionMetrics) => metric.tps,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.tps, 1),
			},
			{
				name: 'Avg Cast',
				tooltip: 'Threat / Casts',
				columnClass: 'threat-metrics',
				getValue: (metric: ActionMetrics) => metric.avgCastThreat,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.avgCastThreat, 1),
			},
			{
				name: 'Avg Hit',
				tooltip: 'Threat / Hits',
				columnClass: 'threat-metrics',
				getValue: (metric: ActionMetrics) => metric.avgHitThreat,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.avgHitThreat, 1),
			},
			{
				name: 'Casts',
				tooltip: 'Casts',
				getValue: (metric: ActionMetrics) => metric.casts,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.casts, 1),
			},
			{
				name: 'Hits',
				tooltip: 'Hits',
				getValue: (metric: ActionMetrics) => metric.landedHits,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.landedHits, 1),
			},
			{
				name: 'Miss %',
				tooltip: 'Misses / Casts',
				getValue: (metric: ActionMetrics) => metric.missPercent,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.missPercent, 2, true, true), // lower is better for misses
			},
			{
				name: 'Crit %',
				tooltip: 'Crits / Hits',
				getValue: (metric: ActionMetrics) => metric.critPercent,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.critPercent, 2, true),
			},
		]);
	}

	customizeRowElem(action: ActionMetrics, rowElem: HTMLElement) {
		if (action.hitAttempts == 0 && action.dps == 0) {
			rowElem.classList.add('threat-metrics');
		}
	}

	getGroupedMetrics(resultData: SimResultData): Array<Array<ActionMetrics>> {
		const players = resultData.result.getPlayers(resultData.filter);
		if (players.length != 1) {
			return [];
		}
		const player = players[0];

		const actions = player.getSpellActions().map(action => action.forTarget(resultData.filter));
		const actionGroups = ActionMetrics.groupById(actions);

		const petsByName = bucket(player.pets, pet => pet.name);
		const petGroups = Object.values(petsByName).map(pets => ActionMetrics.joinById(pets.map(pet => pet.getSpellActions().map(action => action.forTarget(resultData.filter))).flat(), true));

		return actionGroups.concat(petGroups);
	}

	mergeMetrics(metrics: Array<ActionMetrics>): ActionMetrics {
		return ActionMetrics.merge(metrics, true, metrics[0].unit?.petActionId || undefined);
	}

	shouldCollapse(metric: ActionMetrics): boolean {
		return !metric.unit?.isPet;
	}
}
